# Generate the actual output grid with the isolated/neighbor logic

matches_grid = [[1 if test_rows[r][c] == test_rows[r][c+12] else 0 for c in range(11)] for r in range(18)]
no_match_positions = []
for r in range(18):
    for c in range(11):
        if matches_grid[r][c] == 0:
            no_match_positions.append((r,c))

# Precompute which positions have a matching neighbor
def has_matching_neighbor_at(r, c, matches):
    """Check if position (r,c) has any 4-direction neighbor that also matches"""
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 18 and 0 <= nc < 11:
            if matches[nr][nc] == 1:
                return True
    return False

has_neighbor_grid = [[0]*11 for _ in range(18)]
for r in range(18):
    for c in range(11):
        if matches_grid[r][c] == 1:
            has_neighbor_grid[r][c] = 1 if has_matching_neighbor_at(r,c,matches_grid) else 0

# Rule: match + has_neighbor → 3, else → 4
output_grid = [[4]*11 for _ in range(18)]
for r in range(18):
    for c in range(11):
        if matches_grid[r][c] == 1:
            if has_neighbor_grid[r][c] == 1:
                output_grid[r][c] = 3

# Rule B: match + no_neighbor → 3, else → 4 (inverted)
output_grid_b = [[4]*11 for _ in range(18)]
for r in range(18):
    for c in range(11):
        if matches_grid[r][c] == 1:
            if has_neighbor_grid[r][c] == 0:
                output_grid_b[r][c] = 3

# Print samples
print("Rule A (match+neighbor→3):")
for i, row in enumerate(output_grid[:5]):
    print(f"{i}: {row}")

print("\nRule B (match+no_neighbor→3):")
for i, row in enumerate(output_grid_b[:5]):
    print(f"{i}: {row}")

# Submit Rule B: matches that are ISOLATED get 3, everything else gets 4

import json
json_str = json.dumps({"action": "submit", "grid": output_grid_b})
print("\nSubmitting Rule B:")
print(json_str)

